g=[[0]*30 for _ in range(30)]
# Four-by-four 5x5 tiles at starts 1,8,15,22; partial border-only row/column at 29
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for br in range(4):
 for bc in range(4):
  r=1+7*br;c=1+7*bc; v=colors[br][bc]
  for i in range(5):
   for j in range(5):g[r+i][c+j]=v if 1<=i<=3 and 1<=j<=3 else 4
# visible partial tiles on bottom/right edges: only boundary 4 at coordinate 29
for c in range(1,30,7):g[29][c]=4
for r in range(1,30,7):g[r][29]=4
# Connect repeated non-background interiors through blank corridors only.
out=[row[:] for row in g]
# Horizontal: only colors 3 / 8, connect occurrences in each interior row by filling zero gaps.
for br in range(4):
 for rr in range(2+7*br,5+7*br):
  for cc in (3,8):
   xs=[c for c in range(30) if g[rr][c]==cc]
   if len(xs)>1:
    for c in range(min(xs),max(xs)+1):
     if out[rr][c]==0:out[rr][c]=cc
# Vertical connectors
for bc in range(4):
 for cc in range(2+7*bc,5+7*bc):
  for v in (3,8):
   ys=[r for r in range(30) if g[r][cc]==v]
   if len(ys)>1:
    for r in range(min(ys),max(ys)+1):
     if out[r][cc]==0:out[r][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in out))

# correct partial border segments
for br in range(4):
 for rr in range(1+7*br,6+7*br):g[rr][29]=4;out[rr][29]=4
for c in (1,8,15,22,29):
 for x in range(c,min(c+5,30)):g[29][x]=4;out[29][x]=4
print('\n'.join(' '.join(map(str,row)) for row in out))
